const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lake Mead geometry
  const lakeMead = ee.Geometry.Point([-114.5, 36.1]).buffer(15000); // 15km radius

  // 2. Data Acquisition for 2000 (Landsat 7)
  const col2000 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(lakeMead)
    .filterDate('2000-07-01', '2000-07-10')
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  const count2000 = col2000.size().getInfo();
  console.log(`2000 Images found: ${count2000}`);

  if (count2000 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Data Acquisition for 2022 (Landsat 8/9)
  let col2022 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(lakeMead)
    .filterDate('2022-07-01', '2022-07-10')
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  let count2022 = col2022.size().getInfo();

  if (count2022 === 0) {
    // Try Landsat 9
    col2022 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(lakeMead)
      .filterDate('2022-07-01', '2022-07-10')
      .filter(ee.Filter.lt('CLOUD_COVER', 20));
    count2022 = col2022.size().getInfo();
  }

  console.log(`2022 Images found: ${count2022}`);

  if (count2022 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Process 2000 data
  const img2000 = col2000.median();
  const green2000 = img2000.select('SR_B2').multiply(0.0000275).add(-0.2);
  const nir2000 = img2000.select('SR_B4').multiply(0.0000275).add(-0.2);
  const ndwi2000 = green2000.subtract(nir2000).divide(green2000.add(nir2000));
  const water2000 = ndwi2000.gt(0.0);

  // 5. Process 2022 data
  const img2022 = col2022.median();
  const green2022 = img2022.select('SR_B3').multiply(0.0000275).add(-0.2);
  const nir2022 = img2022.select('SR_B5').multiply(0.0000275).add(-0.2);
  const ndwi2022 = green2022.subtract(nir2022).divide(green2022.add(nir2022));
  const water2022 = ndwi2022.gt(0.0);

  // 6. Calculate water pixel counts
  const waterCount2000 = water2000.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeMead,
    scale: 3000,
    maxPixels: 1e9
  }).get('SR_B2').getInfo();

  const waterCount2022 = water2022.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeMead,
    scale: 3000,
    maxPixels: 1e9
  }).get('SR_B3').getInfo();

  console.log(`Water pixels 2000: ${waterCount2000}`);
  console.log(`Water pixels 2022: ${waterCount2022}`);

  // 7. Validation and answer
  if (waterCount2000 === null || waterCount2022 === null) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (waterCount2000 === 0 && waterCount2022 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  const decrease = waterCount2022 < waterCount2000;
  const percentChange = ((waterCount2022 - waterCount2000) / waterCount2000 * 100).toFixed(1);
  console.log(`Change: ${percentChange}%`);

  if (decrease) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
